function validate([n, batteries]) {
  if (!Array.isArray(batteries) || batteries.length < 1 || batteries.length > 100000) return 'batteries needs 1 to 100000 values.';
  if (!Number.isInteger(n) || n < 1 || n > batteries.length) return 'n is between 1 and the number of batteries.';
  if (batteries.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each battery holds 1 to 10^9 minutes.';
  return null;
}

