function maxRunTime(n, batteries) {
  let total = 0;
  for (const power of batteries) {
    total += power;
  }
  let low = 0;
  let high = Math.floor(total / n);

  while (low < high) {
    const mid = Math.floor((low + high + 1) / 2);
    let usable = 0;
    for (const power of batteries) {
      usable += Math.min(power, mid);
    }
    if (usable >= n * mid) {
      low = mid;
    } else {
      high = mid - 1;
    }
  }
  return low;
}

