function maxRunTime(n, batteries) {
  // Greedy: a battery larger than the fair share gets its own computer for good;
  // the rest can be shared perfectly, so the answer is their total over the remaining computers.
  const sorted = batteries.slice().sort((a, b) => b - a);
  let total = sorted.reduce((a, b) => a + b, 0);
  let computers = n;
  let i = 0;
  while (sorted[i] * computers > total) {
    total -= sorted[i];
    computers--;
    i++;
  }
  return Math.floor(total / computers);
}

