function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const length = pick(1500, 2000);
    const n = pick(1, length);
    const top = rand() < 0.5 ? 1000000000 : pick(1, 1000);
    const batteries = Array.from({ length }, () => pick(1, top));
    return [n, batteries];
  }
  const n = pick(1, 4);
  const length = n + pick(0, 5);
  const batteries = Array.from({ length }, () => (rand() < 0.15 ? pick(10, 25) : pick(1, 8)));
  return [n, batteries];
}
